//! `proven`: native tooling for buyers, workers and judges.
//!
//! ```text
//! proven hash <file>                                   SHA-256 of a file's exact bytes
//! proven wat <function.wat>                            function deliverable {"wasm_base64": ...}
//! proven input verify <check.json> <deliverable.json>  the verifier input for OutLayer
//! proven input challenge <check.json> <reference.json>
//! proven run verify <check.json> <deliverable.json>    run the verifier locally
//! proven run challenge <check.json> <reference.json>
//! ```
//! A challenge's fakes are generated by the verifier itself from the reference, so a local
//! `run challenge` shows exactly what the check will face on OutLayer.
//! Output goes to stdout; errors go to stderr.

use proven_verifier::{fakes, run, sha256_hex};
use serde_json::json;
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let words: Vec<&str> = args.iter().map(String::as_str).collect();
    match dispatch(&words) {
        Ok(output) => {
            println!("{output}");
            ExitCode::SUCCESS
        }
        Err(message) => {
            eprintln!("proven: {message}");
            ExitCode::FAILURE
        }
    }
}

fn dispatch(words: &[&str]) -> Result<String, String> {
    match words {
        ["hash", file] => Ok(sha256_hex(&read_bytes(file)?)),
        ["wat", file] => Ok(fakes::deliverable_from_wat(&read(file)?)?.to_string()),
        ["input", mode @ ("verify" | "challenge"), check, other] => input(mode, check, other),
        ["run", mode @ ("verify" | "challenge"), check, other] => Ok(run::run(input(mode, check, other)?.as_bytes())),
        _ => Err("unknown command; see the usage at the top of src/bin/proven.rs".into()),
    }
}

fn input(mode: &str, check: &str, other: &str) -> Result<String, String> {
    let field = if mode == "verify" { "deliverable" } else { "reference" };
    Ok(json!({ "mode": mode, "check": read(check)?, field: read(other)? }).to_string())
}

fn read(path: &str) -> Result<String, String> {
    std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))
}

fn read_bytes(path: &str) -> Result<Vec<u8>, String> {
    std::fs::read(path).map_err(|e| format!("{path}: {e}"))
}
